func isValidPath(directory string) bool {
	// Ensure directory is within the allowed root and does not escape it
	cleanPath := filepath.Clean(directory)
	return !strings.Contains(cleanPath, "..") && !strings.HasPrefix(cleanPath, "/")
}

func main() {
	fmt.Println(isValidPath("../etc"))       // false
	fmt.Println(isValidPath("/absolute"))    // false
